def sector_of(name: str) -> str:
    for sector, names in SECTOR_MAP.items():
        if name in names:
            return sector
    return "متفرقة"


def safe_num(value: Any, default: float = 0.0) -> float:
    try:
        if value is None or (isinstance(value, float) and np.isnan(value)):
            return default
        v = float(value)
        return default if np.isnan(v) else v
    except (TypeError, ValueError):
        return default


def safe_max(series: pd.Series, default: float = 0.0) -> float:
    if series is None or len(series) == 0:
        return default
    val = series.max()
    return default if pd.isna(val) else float(val)


def heat_band(apparent: float) -> str:
    if apparent >= 45:
        return tr("إجهاد شديد", "Extreme stress")
    if apparent >= 40:
        return tr("إجهاد مرتفع", "High stress")
    if apparent >= 35:
        return tr("حار", "Hot")
    return tr("معتدل", "Moderate")


def ops_note(row: pd.Series) -> str:
    notes = []
    if row["Storm Probability"] >= 65:
        notes.append(tr("طيران: راقب خلايا رعدية", "Aviation: watch storms"))
    if row["Fog Probability"] >= 50:
        notes.append(tr("طرق: تدني رؤية", "Roads: low visibility"))
    if row["Shamal Index"] >= 60:
        notes.append(tr("غبار محتمل", "Dust possible"))
    if row["Drizzle Prob"] >= 60:
        notes.append(tr("شرق: رذاذ جبلي", "East: orographic drizzle"))
    if row["Apparent Temp"] >= 42:
        notes.append(tr("عمل خارجي: حدّ من التعرض", "Outdoor work: limit exposure"))
    return " · ".join(notes) if notes else tr("لا قيد تشغيلي بارز", "No major operational limit")


def gfs_cycle(now_utc: datetime) -> str:
    """Latest GFS cycle whose fields are normally available (about 3.5 h after 00/06/12/18 UTC)."""
    ready = now_utc - timedelta(hours=3, minutes=30)
    hour = (ready.hour // 6) * 6
    return ready.strftime("%Y-%m-%d") + f" {hour:02d}Z"


OM_KEY = os.environ.get("OPEN_METEO_API_KEY", "").strip()


def om_url(kind: str = "forecast") -> str:
    paid = {
        "forecast": "https://customer-api.open-meteo.com/v1/forecast",
        "marine": "https://customer-marine-api.open-meteo.com/v1/marine",
        "air": "https://customer-air-quality-api.open-meteo.com/v1/air-quality",
        "archive": "https://customer-archive-api.open-meteo.com/v1/archive",
    }
    free = {
        "forecast": "https://api.open-meteo.com/v1/forecast",
        "marine": "https://marine-api.open-meteo.com/v1/marine",
        "air": "https://air-quality-api.open-meteo.com/v1/air-quality",
        "archive": "https://archive-api.open-meteo.com/v1/archive",
    }
    return paid[kind] if OM_KEY else free[kind]


def om_params(params: Dict[str, Any]) -> Dict[str, Any]:
    ready = dict(params)
    if OM_KEY:
        ready["apikey"] = OM_KEY
    return ready


def om_get(url: str, params: Dict[str, Any], timeout: int = 20):
    return requests.get(url, params=om_params(params), timeout=timeout)
    return requests.get(url, params=params, timeout=timeout)


def fetch_live(stations: Dict[str, Dict], cycle: str) -> Tuple[bool, Any]:
    """Fetch ECMWF, GFS, ICON separately via commercial API and return per-station model data."""
    models = ("ecmwf_ifs", "gfs_seamless", "icon_seamless")
    hourly_vars = "temperature_2m,apparent_temperature,relative_humidity_2m,cape,winddirection_10m,windspeed_10m,windgusts_10m,relative_humidity_850hPa,relative_humidity_700hPa,relative_humidity_500hPa,temperature_850hPa,temperature_500hPa,cloudcover_low,precipitation_probability,visibility,dew_point_2m"
    try:
        lats = ",".join(str(s["lat"]) for s in stations.values())
        lons = ",".join(str(s["lon"]) for s in stations.values())
        names = list(stations.keys())
        per_station = {}
        for model in models:
            params = {
                "latitude": lats,
                "longitude": lons,
                "hourly": hourly_vars,
                "models": model,
                "forecast_days": 5,
                "timezone": "Asia/Dubai",
            }
            r = om_get(om_url("forecast"), params, timeout=40)
            if r.status_code != 200:
                continue
            data = r.json()
            if isinstance(data, dict) and "hourly" in data:
                data = [data]
            elif not isinstance(data, list):
                continue
            for i, name in enumerate(names):
                if i < len(data) and isinstance(data[i], dict) and "hourly" in data[i]:
                    per_station.setdefault(name, {})[model] = data[i]
        if not per_station:
            return False, "No model data received from commercial API"
        return True, per_station
    except Exception as e:
        return False, str(e)


@st.cache_data(ttl=300, show_spinner=False)
def observed_fog_stations() -> set:
    """Return set of ICAO stations currently reporting fog or very low visibility."""
    fogged = set()
    try:
        r = requests.get(
            "https://aviationweather.gov/api/data/metar",
            params={"ids": "OMAA,OMDB,OMAL,OMFJ,OMSJ,OMRK,OMDW", "format": "json"},
            timeout=15,
        )
        if r.status_code != 200:
            return fogged
        for item in r.json():
            raw = (item.get("rawOb") or "").upper()
            station = item.get("icaoId", "")
            if any(code in raw for code in ("FG", "BCFG", "MIFG", "PRFG", "VCFG", "BR")):
                fogged.add(station)
            elif any(x in raw for x in ("1/4SM", "1/2SM", "3/4SM", "1SM")):
                fogged.add(station)
    except Exception:
        pass
    return fogged


def has_observed_storm() -> bool:
    """True only if a current METAR reports thunderstorms or CB."""
    try:
        r = requests.get(
            "https://aviationweather.gov/api/data/metar",
            params={"ids": "OMAA,OMDB,OMAL,OMFJ,OMSJ,OMRK,OMDW", "format": "json"},
            timeout=15,
        )
        if r.status_code != 200:
            return False
        for item in r.json():
            raw = (item.get("rawOb") or "").upper()
            if any(code in raw for code in ("TS", "TSRA", "VCTS", "+TS", "CB", "TCU")):
                return True
    except Exception:
        pass
    return False


@st.cache_data(ttl=6 * 3600, show_spinner=False)
def fetch_oni() -> Tuple[bool, Any]:
    try:
        text = requests.get("https://www.cpc.ncep.noaa.gov/data/indices/oni.ascii.txt", timeout=25).text
        rows = []
        for line in text.splitlines():
            parts = line.split()
            if len(parts) < 4 or parts[0] not in SEASON_ORDER:
                continue
            rows.append({"season": parts[0], "year": int(parts[1]), "sst": float(parts[2]), "anom": float(parts[3])})
        df = pd.DataFrame(rows)
        df["label"] = df["season"] + " " + df["year"].astype(str)
        df["order"] = df["year"] * 12 + df["season"].map({s: i for i, s in enumerate(SEASON_ORDER)})
        return True, df.sort_values("order").reset_index(drop=True)
    except Exception as exc:
        return False, str(exc)


