def compute_probs(hourly, api_times, name, coords, dt):
    temp = app = 35.0
    rh = 50.0
    cloud = wind_dir = wind = gust = storm = fog = alkous = drizzle = shamal = 0.0
    try:
        i = int(np.argmin([abs((t - dt).total_seconds()) for t in api_times]))
        temp = safe_num((hourly.get("temperature_2m") or [None])[i], 35)
        app = safe_num((hourly.get("apparent_temperature") or [temp])[i], temp)
        rh = safe_num((hourly.get("relative_humidity_2m") or [50])[i], 50)
        cloud = safe_num((hourly.get("cloudcover_low") or [0])[i], 0)
        wind_dir = safe_num((hourly.get("winddirection_10m") or [0])[i], 0)
        wind = safe_num((hourly.get("windspeed_10m") or [0])[i], 0)
        gust = safe_num((hourly.get("windgusts_10m") or [wind])[i], wind)
        cape = safe_num((hourly.get("cape") or [0])[i], 0)
        rh850 = safe_num((hourly.get("relative_humidity_850hPa") or [50])[i], 50)
        rh700 = safe_num((hourly.get("relative_humidity_700hPa") or [50])[i], 50)
        rh500 = safe_num((hourly.get("relative_humidity_500hPa") or [50])[i], 50)
        t850 = safe_num((hourly.get("temperature_850hPa") or [20])[i], 20)
        t500 = safe_num((hourly.get("temperature_500hPa") or [-10])[i], -10)
        precip_prob = safe_num((hourly.get("precipitation_probability") or [0])[i], 0)
        elev = ELEVATION.get(name, 0)
        # Strict geographic zones
        east_hajar = coords["lon"] >= 55.9 and (coords["type"] == "Mountains" or elev >= 400)
        central_inland = 24.3 <= coords["lat"] <= 25.1 and 55.4 <= coords["lon"] <= 56.0 and coords["type"] in ("Inland", "Mountains")
        dubai_abudhabi = coords["lon"] < 55.5 and coords["lat"] >= 24.0
        dhafra = coords["type"] == "Desert" or coords["lon"] < 54.2
        moisture = rh850 * 0.45 + rh700 * 0.35 + rh500 * 0.20
        lapse = t850 - t500
        storm = 0.0
        if east_hajar:
            cape_score = max(0, (cape - 220) / 12.0)
            orographic = 15 if cape >= 300 else 0
            storm = cape_score + max(0, (moisture - 48) * 0.6) + precip_prob * 0.5 + orographic
            if cape >= 350 and moisture >= 52:
                storm = max(storm, 40 + cape / 20 + precip_prob * 0.4)
        elif central_inland:
            cape_score = max(0, (cape - 320) / 16.0)
            storm = cape_score + max(0, (moisture - 52) * 0.4) + precip_prob * 0.35
            if cape >= 450 and moisture >= 55:
                storm = max(storm, 25 + cape / 28)
        else:
            # Strong suppression for Dubai, Abu Dhabi, Dhafra and western coast
            storm = max(0, (cape - 500) / 25.0) * 0.3 + precip_prob * 0.15
            if dhafra or dubai_abudhabi:
                storm *= 0.35
        if moisture < 42:
            storm *= 0.4
        storm = float(np.clip(storm, 0, 88))
        # Strong diurnal control: thunderstorms in UAE are rare before midday unless a strong synoptic low is present
        morning = dt.hour < 12
        evening = dt.hour > 19
        if morning or evening:
            # Suppress heavily outside afternoon peak (12-19)
            storm *= 0.25
            # Allow only if very high CAPE + moisture (proxy for synoptic forcing)
            if cape >= 600 and moisture >= 60:
                storm *= 2.0  # partial recovery
        if not (east_hajar or central_inland) and (morning or evening):
            storm *= 0.5
        gulf_coast = coords["type"] == "Coast" and coords["lon"] < 55.6
        oman_coast = coords["lon"] >= 56.15
        if gulf_coast and not east_hajar:
            storm *= 0.4
        if oman_coast and 40 <= wind_dir <= 170 and rh >= 72:
            alkous = max(alkous, float(np.clip((rh - 72) * 2.8, 0, 75)))
            storm *= 0.65
            storm *= 0.3
            if wind >= 28 and (wind_dir >= 300 or wind_dir <= 40):
                shamal = max(shamal, float(np.clip((wind - 26) * 3.5, 0, 90)))
        night = dt.hour >= 18 or dt.hour <= 9
        western = coords["type"] == "Desert" or (coords["type"] == "Coast" and coords["lon"] < 54.6)
        if night and wind < 12 and not east_hajar:
            if western and rh >= 90:
                fog = float(np.clip((rh - 90) * 8 + (12 - wind) * 2, 0, 90))
            elif rh >= 95 and wind < 6:
                fog = float(np.clip((rh - 95) * 6, 0, 75))
            # Al Ain / central inland boost
            if central_inland and rh >= 88 and wind < 8:
                fog = max(fog, float(np.clip((rh - 88) * 7 + (8 - wind) * 1.5, 0, 85)))
        if coords["lon"] >= 55.8 and 45 <= wind_dir <= 160 and rh >= 75 and cloud >= 40:
            base_k = (rh - 75) * 2 + cloud * 0.4
            alkous = float(np.clip(base_k * (1.15 if temp >= 35 else 1), 0, 85))
        if elev >= 800 and 45 <= wind_dir <= 160 and rh >= 70 and cloud >= 50:
            alkous = max(alkous, 35)
            drizzle = max(drizzle, 10)
        if coords["lon"] >= 55.8 and 3 <= dt.hour <= 9 and 45 <= wind_dir <= 160 and rh >= 88 and cloud >= 80:
            drizzle = float(np.clip((rh - 88) * 3.5 + (cloud - 80) * 1.5, 0, 80))
        nw = wind_dir >= 300 or wind_dir <= 30
        southern = 140 <= wind_dir <= 200
        central_inland = 24.0 <= coords["lat"] <= 25.0 and 54.5 <= coords["lon"] <= 55.6 and coords["type"] != "Coast"
        if shamal == 0 and wind >= 28 and nw and coords["type"] in ("Desert", "Coast"):
            shamal = float(np.clip((wind - 26) * 3.5 + 8, 0, 90))
        if wind >= 25 and southern and (central_inland or coords["type"] == "Desert"):
            shamal = max(shamal, float(np.clip((wind - 23) * 3.2 + (10 if central_inland else 4), 0, 90)))
    except Exception:
        pass
    return {
        "storm": storm, "fog": fog, "alkous": alkous, "drizzle": drizzle, "shamal": shamal,
        "temp": temp, "app": app, "rh": rh, "wind": wind, "gust": gust, "wind_dir": wind_dir
    }

rows: List[Dict[str, Any]] = []
if ok and isinstance(live, dict):
    for name, coords in STATIONS.items():
        zone = "Inland" if coords["type"] in ("Inland", "Desert") else coords["type"]
        station_models = live.get(name) or {}
        if not station_models:
            continue
        # Collect probabilities from each available model
        time_probs: Dict[str, List] = {}
        for model_name, station_data in station_models.items():
            hourly = (station_data.get("hourly") or {})
            times = hourly.get("time") or []
            if not times:
                continue
            api_times = [datetime.fromisoformat(t).replace(tzinfo=None) for t in times]
            for dt_str, dt in zip(timeline_str, timeline):
                p = compute_probs(hourly, api_times, name, coords, dt)
                time_probs.setdefault(dt_str, []).append((dt, p))
        for dt_str, items in time_probs.items():
            if not items:
                continue
            dt = items[0][0]
            probs = [item[1] for item in items]
            # Separate by model preference
            ecmwf_storms = [p["storm"] for p in probs if any("ecmwf" in str(k) for k in station_models)]
            icon_rains = [p["drizzle"] for p in probs if any("icon" in str(k) for k in station_models)]
            all_storms = [p["storm"] for p in probs]
            all_drizzles = [p["drizzle"] for p in probs]
            # ECMWF primary for storms, ICON primary for rain
            storm_val = (sum(ecmwf_storms) / len(ecmwf_storms)) if ecmwf_storms else (sum(all_storms) / max(1, len(all_storms)))
            drizzle_val = (sum(icon_rains) / len(icon_rains)) if icon_rains else (sum(all_drizzles) / max(1, len(all_drizzles)))
            # Topographic boost
            elev = ELEVATION.get(name, 0)
            if coords["lon"] >= 55.9 and elev >= 400:
                storm_val = min(90, storm_val * 1.25 + 6)
                drizzle_val = min(85, drizzle_val * 1.15 + 4)
            elif 55.4 <= coords["lon"] <= 56.0 and 24.3 <= coords["lat"] <= 25.1:
                storm_val = min(75, storm_val * 1.1 + 3)
            else:
                storm_val *= 0.55
                drizzle_val *= 0.6
            avg = lambda k: sum(p[k] for p in probs) / len(probs)
            agree_storm = sum(1 for p in probs if p["storm"] >= 70)
            agree_fog = sum(1 for p in probs if p["fog"] >= 75)
            agree_shamal = sum(1 for p in probs if p["shamal"] >= 60)
            agree_drizzle = sum(1 for p in probs if p["drizzle"] >= 50)
            agreement = max(agree_storm, agree_fog, agree_shamal, agree_drizzle)
            rows.append({
                "Time": dt_str, "DateOnly": f"{DAYS_EN[dt.strftime('%A')]} {dt.strftime('%d')}",
                "Station": name, "Sector": sector_of(name), "Zone": zone,
                "Latitude": coords["lat"], "Longitude": coords["lon"],
                "Storm Probability": round(storm_val), "Fog Probability": round(avg("fog")),
                "AlKous Prob": round(avg("alkous")), "Drizzle Prob": round(drizzle_val),
                "Shamal Index": round(avg("shamal")), "Temperature": round(avg("temp"), 1),
                "Apparent Temp": round(avg("app"), 1), "Humidity": round(avg("rh")),
                "Wind": round(avg("wind"), 1), "Gust": round(avg("gust"), 1), "Wind Dir": round(avg("wind_dir")),
                "Agreement": agreement, "ModelsUsed": len(probs),
            })

df = pd.DataFrame(rows)

