def hazard_window(frame: pd.DataFrame, column: str, threshold: float, sector: str, lead_slots: int):
    part = frame[frame["Sector"] == sector] if not frame.empty else frame
    if part.empty or column not in part:
        return None
    active_times = []
    for slot in timeline_str:
        slot_df = part[part["Time"] == slot]
        if not slot_df.empty and safe_max(slot_df[column]) >= threshold:
            active_times.append(slot)
    if not active_times:
        return None
    start_index = timeline_str.index(active_times[0])
    if start_index > lead_slots:
        return None
    run = [active_times[0]]
    previous = start_index
    for slot in active_times[1:]:
        current = timeline_str.index(slot)
        if current == previous + 1:
            run.append(slot)
            previous = current
        else:
            break
    peak_slot = max(run, key=lambda slot: safe_max(part[part["Time"] == slot][column]))
    peak_df = part[part["Time"] == peak_slot].sort_values(column, ascending=False)
    stations = peak_df[peak_df[column] >= threshold]["Station"].head(4).tolist()
    if not stations:
        return None
    joiner = "، " if st.session_state.get("lang") != "en" else ", "
    window = part[part["Time"].isin(run)]
    direction = int(safe_max(peak_df["Wind Dir"])) if "Wind Dir" in peak_df else 0
    wind_min = float(window["Wind"].min()) if "Wind" in window else 0
    wind_max = float(window["Wind"].max()) if "Wind" in window else 0
    fog = safe_max(window["Fog Probability"]) if "Fog Probability" in window else 0
    dust = safe_max(window["Shamal Index"]) if "Shamal Index" in window else 0
    rain = safe_max(window["Drizzle Prob"]) if "Drizzle Prob" in window else 0
    storm = safe_max(window["Storm Probability"]) if "Storm Probability" in window else 0
    if fog >= 70:
        vis = 200
    elif fog >= 50:
        vis = 800
    elif storm >= 60:
        vis = 1500
    elif dust >= 60:
        vis = 2000
    elif rain >= 60:
        vis = 3000
    else:
        vis = 8000
    return run[0], run[-1], int(safe_max(peak_df[column])), joiner.join(stations), start_index == 0, direction, wind_min, wind_max, vis


def rain_words(level: int) -> str:
    if level >= 75:
        return tr("غزيرة", "heavy")
    if level >= 60:
        return tr("متوسطة", "moderate")
    return tr("خفيفة", "light")


alerts = []
if not df.empty:
    checks = [
        ("Fog Probability", 0, 3, "تحذير ضباب", "Fog warning", "تدني الرؤية", "reduced visibility"),  # threshold handled per sector
        ("Storm Probability", 82, 2, "تحذير عواصف", "Storm warning", "عواصف رعدية", "thunderstorms"),
        ("Shamal Index", 60, 6, "تحذير غبار", "Dust warning", "غبار مثار", "raised dust"),
        ("Wind", 45, 6, "تحذير رياح", "Wind warning", "رياح نشطة", "fresh winds"),
        ("Drizzle Prob", 55, 6, "تحذير أمطار", "Rain warning", "احتمال أمطار", "a chance of rain"),
    ]
    for column, threshold, lead, title_ar, title_en, verb_ar, verb_en in checks:
        found_areas = []
        starts, ends = [], []
        occurring = False
        extra = ""
        agree_frame = df[df["Agreement"] >= 2] if "Agreement" in df.columns else df
        for sector in SECTOR_MAP:
            # Per-sector fog thresholds based on geography
            local_threshold = threshold
            if column == "Fog Probability":
                if sector in ("الظفرة", "الساحل الغربي"):
                    local_threshold = 70
                elif sector in ("المنطقة الوسطى", "العين"):
                    local_threshold = 60
                elif sector in ("دبي", "الشارقة وعجمان وأم القيوين"):
                    local_threshold = 75
                else:
                    local_threshold = 80
            found = hazard_window(agree_frame, column, local_threshold, sector, lead)
            # Storms rarely form before late morning in the UAE
            if column == "Storm Probability" and found:
                start_time = found[0]
                try:
                    hour = int(start_time.split(" - ")[1].split(":")[0])
                    if hour < 11 and not has_observed_storm():
                        found = None
                except Exception:
                    pass
            if not found:
                continue
            start, end, level, stations, is_now, direction, wind_min, wind_max, vis = found
            place = SECTOR_EN.get(sector, sector) if lang == "en" else sector
            found_areas.append(f"{place} ({level}%)")
            starts.append(start)
            ends.append(end)
            if column == "Fog Probability":
                fogged = observed_fog_stations()
                # Map stations roughly to sectors
                station_sector = {"OMAL": "العين", "OMAA": "أبوظبي", "OMDB": "دبي", "OMFJ": "الفجيرة", "OMSJ": "الشارقة", "OMRK": "رأس الخيمة", "OMDW": "دبي"}
                occurring = occurring or (is_now and any(station_sector.get(s, "") == sector for s in fogged))
            else:
                occurring = occurring or (is_now and has_observed_storm())
            names = ["شمالية", "شمالية شرقية", "شرقية", "جنوبية شرقية", "جنوبية", "جنوبية غربية", "غربية", "شمالية غربية"]
            wind_bit = tr(
                f" الرياح {names[int((direction + 22.5) // 45) % 8]} تتراوح بين {wind_min:.0f} و {wind_max:.0f} كم/س.",
                f" Wind {direction:.0f}° ranging {wind_min:.0f} to {wind_max:.0f} km/h.",
            )
            vis_bit = tr(f" أدنى رؤية متوقعة {vis:.0f} م.", f" Lowest expected visibility {vis:.0f} m.")
            extra = wind_bit + vis_bit
            if column == "Drizzle Prob":
                extra += tr(f" الشدة {rain_words(level)}.", f" Intensity {rain_words(level)}.")
        if not found_areas:
            continue
        joiner = "، " if lang == "ar" else ", "
        phase = tr("حدوث الآن: ", "Occurring now: ") if occurring else ""
        alerts.append(tr(
            f"{title_ar}: {phase}{verb_ar} على {joiner.join(found_areas)}. من {min(starts)} إلى {max(ends)}.{extra}",
            f"{title_en}: {phase}{verb_en} over {joiner.join(found_areas)}. From {min(starts)} until {max(ends)}.{extra}",
        ))

def sea_alerts():
    points = {"الخليج قرب أبوظبي": (24.50, 54.35), "عمق الخليج": (25.20, 53.40), "بحر عُمان قرب الفجيرة": (25.15, 56.45), "عمق بحر عُمان": (25.00, 57.20)}
    try:
        response = requests.get(
            om_url("marine"),
            params={
                "latitude": ",".join(str(v[0]) for v in points.values()),
                "longitude": ",".join(str(v[1]) for v in points.values()),
                "hourly": "wave_height",
                "forecast_days": 2,
                "timezone": "Asia/Dubai",
            },
            timeout=25,
        )
        response.raise_for_status()
        payload = response.json()
        rows = payload if isinstance(payload, list) else [payload]
    except Exception:
        return []
    lines = []
    for (name, _), row in zip(points.items(), rows):
        hourly = row.get("hourly") or {}
        heights = hourly.get("wave_height") or []
        upcoming = [safe_num(h, 0) for h in heights[:7]]
        if not upcoming or max(upcoming) < 1.0:
            continue
        peak = max(upcoming)
        feet = peak * 3.28084
        when = "الآن" if upcoming[0] >= 1.0 else "خلال 6 ساعات"
        lines.append(tr(
            f"تحذير اضطراب بحر — {when}: {name}، ارتفاع الموج {feet:.0f} قدم ({peak:.1f} م).",
            f"Sea warning — {when}: {name}, waves {feet:.0f} ft ({peak:.1f} m).",
        ))
    return lines

alerts.extend(sea_alerts())

