def fetch_nowcast() -> Tuple[bool, Any]:
    points = {"ناهل": (24.616, 55.575), "الفقع": (24.716, 55.620), "العجبان": (24.600, 55.300), "سويحان": (24.466, 55.330), "الشويب": (24.780, 55.800), "مسافي": (25.310, 56.160), "العين": (24.220, 55.760)}
    try:
        response = requests.get(
            om_url("forecast"),
            params={
                "latitude": ",".join(str(v[0]) for v in points.values()),
                "longitude": ",".join(str(v[1]) for v in points.values()),
                "current": "precipitation,weather_code,cloud_cover",
                "timezone": "Asia/Dubai",
            },
            timeout=25,
        )
        response.raise_for_status()
        payload = response.json()
        return True, list(zip(points, payload if isinstance(payload, list) else [payload]))
    except Exception as exc:
        return False, str(exc)

now_ok, nowcast = fetch_nowcast()
if now_ok:
    wet = []
    for name, payload in nowcast:
        current = payload.get("current") or {}
        rain = safe_num(current.get("precipitation"), 0)
        code = int(safe_num(current.get("weather_code"), 0))
        if rain >= 0.2 or code in (80, 81, 82, 95, 96, 99, 61, 63, 65):
            wet.append(f"{name} ({rain:.1f} مم)")
    if wet:
        alerts.insert(0, tr(
            f"تنبيه حدوث: مطر أو سحب رعدية على {'، '.join(wet)}.",
            f"Occurrence alert: rain or thunder at {', '.join(wet)}.",
        ))
badge = len(alerts)
try:
    state_path = "/tmp/71wm_alert_state.txt"
    # Language-independent key: based only on alert count and numeric content
    import hashlib, re
    stable_parts = []
    for a in alerts:
        # extract numbers and key weather words only
        nums = re.findall(r'\d+(?:\.\d+)?', a)
        words = re.findall(r'(ضباب|عواصف|غبار|رياح|أمطار|بحر|Fog|Storm|Dust|Wind|Rain|Sea)', a)
        stable_parts.append("|".join(nums + words))
    current_key = hashlib.md5("\n".join(sorted(stable_parts)).encode()).hexdigest() if stable_parts else "none"
    previous = open(state_path, encoding="utf-8").read() if os.path.exists(state_path) else ""
    if current_key != previous:
        message = "\n".join(alerts) or "انتهى التحذير. لا خطر قائم حالياً."
        headers = {"Title": "71WM warning", "Priority": "high", "Tags": "warning", "Content-Type": "text/plain; charset=utf-8"}
        token = os.getenv("NTFY_TOKEN", "")
        if token:
            headers["Authorization"] = f"Bearer {token}"
        requests.post(
            "https://ntfy.sh/71wm-alkindi-uae",
            data=message.encode("utf-8"),
            headers=headers,
            timeout=8,
        )
        alexa_token = os.getenv("ALEXA_TOKEN", "")
        alexa_devices = [item.strip() for item in os.getenv("ALEXA_DEVICE", "").split(",") if item.strip()]
        extra = os.getenv("ALEXA_DEVICE_2", "").strip()
        if extra:
            alexa_devices.append(extra)
        for alexa_device in alexa_devices:
            if alexa_token and alexa_device:
                requests.post(
                    "https://api-v3.voicemonkey.io/announce",
                    json={"token": alexa_token, "device": alexa_device, "speech": message},
                    timeout=8,
                )
        open(state_path, "w", encoding="utf-8").write(current_key)
except Exception:
    pass

