def layer_map(kind: str, radar_url: str = "") -> str:
    overlay = ""
    max_zoom = 18
    if kind == "Radar" and radar_url:
        overlay = f"L.tileLayer({json.dumps(radar_url)}, {{opacity: 0.8, maxZoom: 7, maxNativeZoom: 7}}).addTo(map);"
        max_zoom = 8
    if kind == "Satellite":
        overlay = "L.tileLayer('https://tilecache.rainviewer.com/v2/satellite/0/256/{z}/{x}/{y}/0/0_0.png', {opacity: 0.85, maxZoom: 8, maxNativeZoom: 8}).addTo(map);"
        max_zoom = 8
    return f"""
    <link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"/>
    <div id="uaemap" style="height:640px;border-radius:16px;background:#e5e7eb"></div>
    <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
    <script>
      var map = L.map('uaemap', {{maxZoom: {max_zoom}}}).setView([24.4, 54.6], 6);
      L.tileLayer('https://{{s}}.tile.openstreetmap.org/{{z}}/{{x}}/{{y}}.png', {{maxZoom: 18, attribution: '© OpenStreetMap'}}).addTo(map);
      {overlay}
    </script>
    """


def windy_map(frame: pd.DataFrame, field: str, title: str, scale: str, zoom: float = 6.2):
    places = [
        ("أبوظبي", 24.45, 54.38, 5), ("دبي", 25.20, 55.27, 5), ("الشارقة", 25.35, 55.40, 5),
        ("عجمان", 25.40, 55.48, 6), ("أم القيوين", 25.56, 55.55, 6), ("رأس الخيمة", 25.79, 55.94, 5),
        ("الفجيرة", 25.12, 56.33, 5), ("العين", 24.21, 55.74, 5), ("الظفرة", 23.70, 53.70, 5),
        ("خورفكان", 25.33, 56.35, 6.5), ("حتا", 24.80, 56.12, 6.5), ("مدينة زايد", 23.65, 53.70, 6.5),
        ("ليوا", 23.13, 53.77, 6.5), ("دلما", 24.50, 52.30, 6.5), ("المدام", 24.95, 55.78, 6.5),
        ("كلباء", 25.05, 56.35, 7.2), ("مسافي", 25.30, 56.16, 7.2), ("سويحان", 24.46, 55.35, 7.2),
        ("الذيد", 25.24, 55.82, 7.2), ("غياثي", 23.84, 52.81, 7.2), ("الرويس", 24.11, 52.73, 7.2),
    ]
    if frame.empty or (field not in frame and field != "Sea"):
        fig = go.Figure()
        fig.update_layout(title=title, height=640, mapbox_style="open-street-map", mapbox_center=dict(lat=24.4, lon=54.6), mapbox_zoom=zoom)
        return fig
    work = frame.copy()
    names = ["شمالية", "شمالية شرقية", "شرقية", "جنوبية شرقية", "جنوبية", "جنوبية غربية", "غربية", "شمالية غربية"]
    if field == "Sea":
        sea = fetch_wave_points()
        if sea.empty:
            fig = go.Figure()
            fig.update_layout(title=title, height=640, mapbox_style="open-street-map", mapbox_center=dict(lat=24.4, lon=54.6), mapbox_zoom=zoom)
            return fig
        work = sea
        field = "Wave"
    if field == "Wind":
        work["اتجاه"] = work["Wind Dir"].map(lambda d: names[int((float(d) + 22.5) // 45) % 8])
        work["الرياح"] = work.apply(lambda r: f"{r['Wind']:.0f} كم/س · {r['اتجاه']}", axis=1)
    colors = {"Rain": "Blues", "Storm Probability": "Hot", "Wind": "YlOrRd", "Shamal Index": "Oranges", "Fog Probability": "Blues", "Wave": "Teal", "Temperature": "Jet"}
    if field == "Temperature":
        work["الحرارة"] = work["Temperature"].map(lambda v: f"{v:.0f} °C")
    hover = {"Wave": ["الارتفاع"], "Wind": ["الرياح"], "Temperature": ["الحرارة"]}
    zmin, zmax = (None, None) if field == "Temperature" else ((0, 3) if field == "Wave" else (0, 100))
    fig = px.density_mapbox(
        work, lat="Latitude", lon="Longitude", z=field, radius=28,
        color_continuous_scale=colors.get(scale if field != "Wave" else "Wave", "Hot"),
        range_color=(zmin, zmax), zoom=zoom, center=dict(lat=24.3, lon=54.8),
        mapbox_style="carto-positron", title=title, hover_name="Station",
    )
    unit = {"Temperature": "°", "Wave": " م", "Wind": ""}.get(field, "%")
    fig.add_trace(go.Scattermapbox(
        lat=work["Latitude"], lon=work["Longitude"], mode="markers+text",
        marker=dict(size=8, color="white", opacity=0.8),
        text=work[field].map(lambda v: f"{v:.0f}{unit}"),
        textposition="top center", textfont=dict(size=12, color="#111827"),
        hoverinfo="skip", name="القيمة",
    ))
    if field == "Wind" and "Wind Dir" in work:
        tips_lat, tips_lon = [], []
        for _, row in work.iterrows():
            rad = math.radians(float(row["Wind Dir"]))
            tips_lat += [row["Latitude"], row["Latitude"] + 0.16 * math.cos(rad), None]
            tips_lon += [row["Longitude"], row["Longitude"] + 0.16 * math.sin(rad), None]
        fig.add_trace(go.Scattermapbox(lat=tips_lat, lon=tips_lon, mode="lines", line=dict(width=3, color="#1e3a8a"), hoverinfo="skip", name="اتجاه"))
        fig.add_trace(go.Scattermapbox(
            lat=work["Latitude"], lon=work["Longitude"], mode="text",
            text=work["الرياح"], textposition="top center", textfont=dict(size=11, color="#111827"),
            hoverinfo="skip", name="السرعة",
        ))
    shown = [p for p in places if zoom + 0.2 >= p[3]]
    if shown:
        fig.add_trace(go.Scattermapbox(
            lat=[p[1] for p in shown], lon=[p[2] for p in shown], mode="text",
            text=[p[0] for p in shown], textfont=dict(size=13, color="#111827"),
            hoverinfo="skip", name="المناطق",
        ))
    fig.update_layout(margin=dict(l=0, r=0, t=36, b=0), height=680, paper_bgcolor="#f8fafc", font=dict(color="#111827", size=14), mapbox=dict(style="carto-positron", center=dict(lat=24.3, lon=54.8), zoom=zoom), uirevision=str(zoom))
    return fig


